ROOT=pathlib.Path(__file__).resolve().parents[1]
D=load_results(ROOT/'shared')['studies']
fmt=lambda x,d=2:f'{x:,.{d}f}'

studies=[
dict(kind='credit',slug='01-credit-risk',domain='Credit Risk Intelligence',title='The Interest-Burden Threshold Test',subtitle='When household interest intensity rises, does reported payment strain become more predictable?',
 brief=[f"In the latest matched year ({D['credit']['latest_year']}), {fmt(D['credit']['latest_burden'],1)}% of households paid at least 15% of total income in interest; {fmt(D['credit']['latest_problem'],1)}% of persons reported housing-payment problems.",f"Across {len(D['credit']['backtest'])} expanding one-year origins, the burden-plus-persistence rule records MAE {fmt(D['credit']['model_mae'],3)} pp versus {fmt(D['credit']['baseline_mae'],3)} pp for persistence.",f"The candidate is worse by {fmt(D['credit']['model_mae']-D['credit']['baseline_mae'],3)} pp on the point estimate.",f"The 95% two-year-block interval for baseline-minus-model improvement is {fmt(D['credit']['improvement_ci'][0],3)} to {fmt(D['credit']['improvement_ci'][1],3)} pp; predictive superiority is not established."],
 mechanism='High interest payments compress household cash flow, but distributional burden and realised payment problems are not the same object. Income recovery, liquid buffers and refinancing can break the apparent pass-through. The test therefore asks whether the burden share adds forward information beyond simply carrying the last strain reading forward.',
 method='SSB 08727: household share by interest paid as a percentage of total income, 2006–2024. Sum the disjoint 15–20, 20–30, 30–40 and 40+ bins. SSB 12128: percentage reporting problems paying housing costs, all income groups, 2011–2025. Match common years. At each origin fit next-year strain on the current strain and current ≥15% burden share using only earlier rows; compare with persistence. Retain the last eight eligible origins. Circular two-year blocks, 5,000 draws, seed 20261122.',
 limits=D['credit']['limits'],change=['Exposure-weighted arrears and balances tied to the same households.','An untouched sequence of survey vintages with a stable loss advantage.','A result robust to alternative burden thresholds, income groups and real-time revisions.'],
 decision=[['Credit risk','Retain persistence as reference','Borrower-level arrears and exposures','Survey strain is not PD.'],['Affordability','Use burden segments as monitoring prompts','Income and liquidity buffers','Household types are not loan cohorts.'],['Model governance','Shadow-run the candidate','Longer genuine forward record','Interval crosses zero.']],
 inputs=[dict(id='burdenShift',label='Interest-burden shift · pp',value=0,min=-20,max=30,step=.5),dict(id='strainElasticity',label='Assumed strain response · pp per burden pp',value=.1,min=0,max=2,step=.05),dict(id='incomeShock',label='Additional income shock · pp',value=0,min=-5,max=15,step=.25),dict(id='persistenceDrift',label='Annual scenario drift · pp',value=0,min=-2,max=5,step=.1)],source='https://www.ssb.no/en/statbank/table/08727/'),
dict(kind='financial',slug='02-financial',domain='Financial Intelligence',title='The Policy-Rate Signal Test',subtitle='Can the Norwegian policy rate improve a monthly EUR/NOK random-walk baseline?',
 brief=[f"The retained monthly history runs through {D['financial']['latest']['date']}: EUR/NOK {fmt(D['financial']['latest']['eurnok'],4)} and an average policy rate of {fmt(D['financial']['latest']['policy_rate'],2)}%.",f"Across {len(D['financial']['backtest'])} expanding monthly origins, the signal model has MAE {fmt(D['financial']['model_mae'],3)}% versus {fmt(D['financial']['baseline_mae'],3)}% for a zero-return random walk.",f"Directional accuracy is {fmt(100*D['financial']['direction_accuracy'],1)}%.",f"The three-month-block 95% interval for mean MAE improvement is {fmt(D['financial']['improvement_ci'][0],3)} to {fmt(D['financial']['improvement_ci'][1],3)} percentage points; it crosses zero."],
 mechanism='A higher domestic rate can support a currency through carry, yet the same rate can signal inflation or macro stress. EUR/NOK also absorbs foreign rates, energy prices and global risk appetite. A statistically richer story earns credibility only if it improves the next-month random-walk baseline.',
 method='Norges Bank monthly EUR/NOK middle rates and daily key policy-rate observations, January 2000–October 2026. Aggregate the policy rate to monthly mean; compute monthly log EUR/NOK changes. At every one of the final 71 origins, re-estimate next-month change on the current change, current rate change and current rate level using only earlier rows. Compare with zero return. Circular three-month blocks, 5,000 draws, seed 20261122.',
 limits=D['financial']['limits'],change=['Foreign policy rates, energy prices and risk factors in a pre-specified model.','A stable net advantage after spreads, slippage and new untouched months.','Evidence that the effect survives alternative horizons and rate aggregations.'],
 decision=[['Treasury','Keep random walk visible','Executable quotes and hedge mandate','Middle rates are indicative.'],['FX risk','Treat rate signal as a scenario input','Foreign-rate and energy controls','No carry-return claim.'],['Model governance','Monitor loss differential','New untouched monthly record','Confidence interval crosses zero.']],
 inputs=[dict(id='rateShock',label='Policy-rate shock · pp',value=0,min=-5,max=5,step=.25),dict(id='rateSensitivity',label='Assumed monthly FX response · % per rate pp',value=-.2,min=-5,max=5,step=.1),dict(id='monthlyFxMove',label='Other monthly EUR/NOK move · %',value=0,min=-10,max=10,step=.25)],source='https://www.norges-bank.no/en/topics/Statistics/exchange_rates/'),
dict(kind='accounting',slug='03-accounting',domain='Accounting & Audit Intelligence',title='The Working-Capital Warning Test',subtitle='Receivables, inventory and payables as a forward cash-conversion diagnostic',
 brief=[f"The panel contains {D['accounting']['issuers']} SEC issuers and {len(D['accounting']['backtest'])} issuer-year holdouts.",f"The working-capital model records MAE {fmt(D['accounting']['model_mae'])} pp of CFO margin versus {fmt(D['accounting']['baseline_mae'])} pp for the prior-year margin.",f"The candidate is worse by {fmt(D['accounting']['model_mae']-D['accounting']['baseline_mae'])} pp on the point estimate.",f"The issuer-cluster 95% interval for baseline-minus-model improvement is {fmt(D['accounting']['cluster_ci'][0])} to {fmt(D['accounting']['cluster_ci'][1])} pp and includes zero."],
 mechanism='Working-capital absorption can precede weaker cash conversion, but receivables and inventory may also finance real growth. A warning indicator is useful only if it improves the next filing beyond the prior cash-flow margin and remains stable across issuers.',
 method='SEC Company Facts for Microsoft, Alphabet, Amazon, Meta, NVIDIA and Oracle, USD, form 10-K, filed no later than 21 November 2026. Annual flow duration 330–380 days. CFO margin = operating cash flow / revenue. Working-capital absorption = (Δreceivables + Δinventory − Δcurrent payables) / revenue. For the final three eligible targets per issuer, fit a pooled ridge model on earlier non-holdout issuer-years using lag CFO margin and lag absorption; compare with lag CFO margin. Resample issuers as clusters, 5,000 draws.',
 limits=D['accounting']['limits'],change=['Footnote-reconciled working capital including contract balances and deferred revenue.','A pre-specified sector expansion with an untouched filing period.','A stable advantage under alternative tag fallbacks and restatement vintages.'],
 decision=[['Audit planning','Retain prior margin as baseline','Footnote and accession review','Candidate does not outperform.'],['Credit analyst','Separate growth from deterioration','Orders, ageing and inventory quality','Absorption is not distress.'],['Data governance','Preserve tags and filing dates','Restatement lineage','Latest vintage is not real time.']],
 inputs=[dict(id='revenueChange',label='Revenue change · %',value=0,min=-60,max=100,step=5),dict(id='cfoChange',label='Operating cash-flow change · %',value=0,min=-100,max=150,step=5),dict(id='wcDrag',label='Working-capital drag · pp of margin',value=0,min=-20,max=40,step=1)],source='https://www.sec.gov/search-filings/edgar-application-programming-interfaces'),
dict(kind='governance',slug='04-governance',domain='Risk & Governance Intelligence',title='The Voice-to-Capital Mismatch',subtitle='Where reported voting rights and economic ownership cease to be interchangeable',
 brief=[f"The 30 June 2026 NBIM equity snapshot contains {D['governance']['holdings']:,} holdings with both voting and ownership percentages.",f"The capital-weighted absolute voting–ownership gap is {fmt(D['governance']['weighted_abs_gap_pp'],3)} percentage points; the raw correlation is {fmt(D['governance']['correlation'],3)}.",f"At a 0.10 pp gap threshold, {D['governance']['sensitivity'][0]['holdings']:,} holdings qualify and represent {fmt(D['governance']['sensitivity'][0]['value_share_pct'])}% of analysed market value.",f"Value with a voting discount beyond 0.10 pp represents {fmt(D['governance']['vote_discount_value_pct'])}% of value, versus {fmt(D['governance']['vote_premium_value_pct'])}% with a voting premium."],
 mechanism='Stewardship teams often use capital exposure as a proxy for voice. Dual-class structures, share lending and market rules can break that equivalence. The map identifies where a value-based queue may misstate formal voting capacity; it does not infer influence or governance quality.',
 method='NBIM listed-equity holdings report dated 30 June 2026, UTF-16 semicolon-separated CSV. Retain rows with numeric market value, voting percentage and ownership percentage. Gap = voting − ownership; report absolute gap, value-weighted absolute gap and threshold sensitivity at 0.10/0.25/0.50/1.00/2.00 pp. Denominator is market value of retained rows. Snapshot analysis; forecast backtesting is not applicable.',
 limits=D['governance']['limits'],change=['Meeting-specific vote eligibility and share-class legal mappings.','Time-series holdings proving that gaps persist.','Engagement outcomes demonstrating that formal vote gaps alter stewardship effectiveness.'],
 decision=[['Stewardship','Flag large voice gaps','Share-class and meeting verification','Gap is not influence.'],['Risk committee','Separate capital from vote capacity','Securities lending and local rules','Snapshot only.'],['Data governance','Retain both fields','Issuer/share-class identifiers','Do not substitute ownership for voting.']],
 inputs=[dict(id='gapThreshold',label='Absolute voice-gap threshold · pp',value=.1,min=0,max=10,step=.05),dict(id='minValueBn',label='Minimum holding value · NOK bn',value=0,min=0,max=500,step=1),dict(id='valueShock',label='Uniform value shock · %',value=0,min=-80,max=100,step=5)],source='https://www.nbim.no/en/investments/all-investments/'),
dict(kind='business',slug='05-business',domain='Business & Economic Intelligence',title='The Digital-Readiness Conversion Test',subtitle='Does basic digital intensity improve a next-year AI-adoption baseline?',
 brief=[f"Across ten European countries, the correlation between 2024 basic digital intensity and 2025 AI use is {fmt(D['business']['latest_correlation'],3)}.",f"Leave-one-country-out MAE is {fmt(D['business']['model_mae'])} pp for the readiness model versus {fmt(D['business']['baseline_mae'])} pp for 2024 AI-use persistence.",f"The cross-country resampling interval for mean baseline-minus-model improvement is {fmt(D['business']['country_ci'][0])} to {fmt(D['business']['country_ci'][1])} pp.","Norway moves from 20.77% AI use in 2024 to 28.89% in 2025, with 83.45% at basic digital intensity in 2024."],
 mechanism='Digital readiness can lower implementation friction, but it does not guarantee useful AI deployment. The model tests whether a broad capability measure adds cross-country information beyond last year’s adoption level. The design validates across countries, not across an untouched future year.',
 method='Eurostat dissemination datasets isoc_e_dii and isoc_eb_ain2. Ten countries: Norway, Denmark, Sweden, Finland, Germany, France, Netherlands, Belgium, Ireland and Poland. Retain enterprises with 10+ persons, all covered non-financial activities, percentage of enterprises. DII version 4 at least-basic level in 2024; AI use in 2024 and 2025. For each country, fit on the other nine and predict its 2025 AI use from 2024 DII and 2024 AI use. Compare with 2024 AI-use persistence. Country resampling, 5,000 draws.',
 limits=D['business']['limits'],change=['A genuinely untouched 2026 survey vintage using unchanged definitions.','Firm-level transitions and AI-spend/productivity outcomes.','Sampling errors supporting design-based inference.'],
 decision=[['Strategy','Use readiness as a screening variable','Use-case and productivity data','Readiness is not ROI.'],['Investor','Separate capability from adoption','Spend, margins and implementation depth','Cross-country holdout only.'],['Data governance','Lock DII version and scope','Survey revision documentation','Do not mix versions.']],
 inputs=[dict(id='readinessGain',label='Annual readiness change · pp',value=2,min=-20,max=30,step=1),dict(id='conversion',label='Assumed AI response per readiness pp',value=.3,min=0,max=2,step=.05),dict(id='adoptionMomentum',label='Other annual AI momentum · pp',value=3,min=-20,max=30,step=1)],source='https://ec.europa.eu/eurostat/databrowser/view/isoc_e_dii/default/table'),
dict(kind='public_finance',slug='06-public-finance',domain='Public Finance Intelligence',title='The Sovereign Interest-Pass-Through Test',subtitle='Can the policy rate improve Norway’s next-year net-interest baseline?',
 brief=[f"In {int(D['public_finance']['latest']['year'])}, consolidated government interest income was NOK {fmt(D['public_finance']['latest']['interest_income_nok_million']/1000)}bn and interest expense NOK {fmt(D['public_finance']['latest']['interest_expense_nok_million']/1000)}bn.",f"The resulting net interest position was NOK {fmt(D['public_finance']['latest']['net_interest_nok_million']/1000)}bn with an annual-average policy rate of {fmt(D['public_finance']['latest']['policy_rate'],2)}%.",f"Across the final ten origins, the rate-signal model has MAE NOK {fmt(D['public_finance']['model_mae_nok_million']/1000)}bn versus NOK {fmt(D['public_finance']['baseline_mae_nok_million']/1000)}bn for persistence.",f"The two-year-block 95% interval for baseline-minus-model improvement is NOK {fmt(D['public_finance']['improvement_ci_nok_million'][0]/1000)}bn to {fmt(D['public_finance']['improvement_ci_nok_million'][1]/1000)}bn; it crosses zero."],
 mechanism='A higher policy rate does not reprice public assets and liabilities symmetrically. Maturity, currency and asset composition determine pass-through. The test asks whether a coarse rate signal adds next-year forecasting information beyond the observed net interest position.',
 method='SSB 10721, consolidated general government, nominal NOK million, interest income A51 and interest expense B41, 1995–2024. Norges Bank daily key policy rate aggregated to annual mean from 2000. Net position = income − expense. At each origin fit next-year net interest on current net interest, current rate level and rate change using only earlier rows; compare with persistence. Retain final ten origins. Circular two-year blocks, 5,000 draws.',
 limits=D['public_finance']['limits'],change=['Instrument-level maturity, currency and duration data.','Real-time fiscal vintages and an untouched new year.','A stable advantage after separating GPFG and mainland government exposures.'],
 decision=[['Fiscal analyst','Retain persistence reference','Duration and currency map','Not fiscal-rule headroom.'],['Treasury','Stress income and expense separately','Instrument repricing schedule','Policy rate is coarse.'],['Risk committee','Avoid sovereign-solvency inference','Balance sheet and structural balance','Nominal flow only.']],
 inputs=[dict(id='rateShock',label='Sustained rate shock · pp',value=1,min=-5,max=5,step=.25),dict(id='incomePassThrough',label='Income pass-through · % per rate pp',value=5,min=-20,max=40,step=1),dict(id='expensePassThrough',label='Expense pass-through · % per rate pp',value=5,min=-20,max=40,step=1)],source='https://www.ssb.no/en/statbank/table/10721/'),
dict(kind='art',slug='07-art-capital',domain='Art & Capital Intelligence',title='The Museum Subsidy Resilience Test',subtitle='Public funding, own revenue and the limits of predicting cultural demand',
 brief=[f"In {int(D['art']['latest']['year'])}, Norwegian museums recorded {fmt(D['art']['latest']['total_visits']/1e6,2)} million individual-plus-group visits.",f"Public contributions were NOK {fmt(D['art']['latest']['public_contributions_nok_million']/1000,2)}bn, equal to {fmt(D['art']['latest']['subsidy_share_pct'],1)}% of total nominal revenue.",f"Own revenue was NOK {fmt(D['art']['latest']['own_revenue_nok_million']/1000,2)}bn, or approximately NOK {fmt(D['art']['latest']['own_revenue_per_visit_nok'],0)} per visit.",f"Across the final ten origins, the subsidy-share model has MAE {fmt(D['art']['model_mae_visits']/1e6,3)}m visits versus {fmt(D['art']['baseline_mae_visits']/1e6,3)}m for persistence; the interval crosses zero."],
 mechanism='Public subsidy can stabilise cultural institutions without mechanically generating visitors. Funding may rise precisely when earned income or attendance is weak, creating reverse causality. The study separates financial resilience from demand prediction and treats the subsidy share as a signal, not an intervention effect.',
 method='SSB 09542 national museum revenue, expenditure and public contributions, and SSB 09539 visits, 2001–2024. Total visits = individual visits + group visits; paying visits overlap and are not added. Subsidy share = public contributions / total revenue; own revenue = total revenue − public contributions. At each origin fit next-year total visits on current visits and subsidy share using only earlier rows; compare with persistence. Retain final ten origins; report pandemic-excluded MAE separately. Circular two-year blocks, 5,000 draws.',
 limits=D['art']['limits'],change=['Institution-level panel data with consistent museum population.','Deflated revenue, ticket prices and exhibition-level demand.','An exogenous funding design separating subsidy causality from need-based allocation.'],
 decision=[['Museum board','Separate resilience from demand','Institution and exhibition data','Subsidy share is not attendance causality.'],['Public funder','Monitor own revenue per visit','Access, quality and distribution goals','Commercialisation is not the sole objective.'],['Cultural investor','Treat aggregates as sector context','Institution-level balance sheets','No art-return claim.']],
 inputs=[dict(id='publicChange',label='Public-contribution change · %',value=0,min=-50,max=100,step=5),dict(id='ownChange',label='Own-revenue change · %',value=0,min=-80,max=150,step=5),dict(id='visitChange',label='Visit change · %',value=0,min=-80,max=100,step=5)],source='https://www.ssb.no/en/statbank/table/09542/')]

(ROOT/'shared/studies.json').write_text(json.dumps(studies,indent=2,ensure_ascii=False))
def esc(x): return html.escape(str(x),quote=True)
def dashboard(c):
 inputs=''.join(f'<label for="{x["id"]}">{esc(x["label"])}<input id="{x["id"]}" type="number" min="{x["min"]}" max="{x["max"]}" step="{x["step"]}" value="{x["value"]}"></label>' for x in c['inputs'])
 brief=''.join(f'<li>{esc(x)}</li>' for x in c['brief']); changes=''.join(f'<li>{esc(x)}</li>' for x in c['change']); decisions=''.join('<tr>'+''.join(f'<td>{esc(v)}</td>' for v in row)+'</tr>' for row in c['decision'])
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(c['title'])} | Financial &amp; Risk Intelligence</title><link rel="stylesheet" href="../shared/app.css"></head><body><header><nav><a href="/">← Main research portfolio</a> <a href="../">Weekly release</a> <a href="../shared/audit.html">Audit &amp; sources</a></nav></header><main><div class="eyebrow">22 November 2026 / {esc(c['domain'])}</div><h1>{esc(c['title'])}</h1><p class="lead">{esc(c['subtitle'])}</p><div class="ribbon">EMPIRICAL EVIDENCE · EXPLICIT LIMITATIONS · USER SCENARIOS</div><section><h2>Research Intelligence Brief</h2><ol>{brief}</ol></section><section><h2>The mechanism and the test</h2><p>{esc(c['mechanism'])}</p></section><section><h2>Evidence explorer</h2><label for="choice">Explore sample<select id="choice"></select></label><p id="evidence-note"></p><div id="chart" class="chart"></div><div id="chart2" class="chart"></div><details><summary>Inspect observations and source fields</summary><div id="table" class="tablewrap"></div></details><button id="csv">Export selected evidence · CSV</button></section><section id="playground"><div class="eyebrow">USER SCENARIO — NOT AN EMPIRICAL RESULT</div><h2>Interactive playground</h2><p id="lab-note"></p><div class="controls">{inputs}</div><div id="result" class="result" aria-live="polite"></div><div id="scenario-chart" class="chart"></div><button id="reset">Reset assumptions</button> <button id="export">Export scenario · JSON</button></section><section><h2>Decision Matrix</h2><div class="tablewrap"><table><thead><tr><th>Decision owner</th><th>Action</th><th>Required evidence</th><th>Boundary</th></tr></thead><tbody>{decisions}</tbody></table></div></section><section><h2>Methodology &amp; limitations</h2><p>{esc(c['method'])}</p><p class="warning">{esc(c['limits'])}</p><a href="methodology.html">Separate methodology page →</a></section><section><h2>What Would Change Our Mind</h2><ul>{changes}</ul></section><section><h2>Sources &amp; reproducibility</h2><p><a href="{esc(c['source'])}">Official source</a> · <a href="../shared/results.json">Research data</a> · <a href="../shared/analyze.py">Analysis code</a> · <a href="../shared/reproduce.py">Reproduction runner</a> · <a href="../shared/audit.html">Audit and source manifest</a></p><p>Source publication dates, extraction dates and observation periods are kept distinct. Historical data are not relabelled as observations from today.</p></section><script id="config" type="application/json">{json.dumps(c,ensure_ascii=False).replace('</','<\\/')}</script><script src="../shared/app.js"></script></main><footer>Independent research · Public-source evidence · 22 November 2026 · Scenarios are assumptions, not forecasts.</footer></body></html>'''
def methodology(c):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Methodology | {esc(c['title'])}</title><link rel="stylesheet" href="../shared/app.css"></head><body><header><nav><a href="./">← Dashboard</a> <a href="../shared/audit.html">Audit &amp; sources</a></nav></header><main><div class="eyebrow">Methodology / 22 November 2026</div><h1>{esc(c['title'])}</h1><section><h2>Research question</h2><p>{esc(c['subtitle'])}</p></section><section><h2>Data and calculation</h2><p>{esc(c['method'])}</p></section><section><h2>Identification boundary</h2><p class="warning">{esc(c['limits'])}</p></section><section><h2>Validation classification</h2><p>Temporal holdouts use only earlier rows at each origin but rely on the latest published vintage unless explicitly stated. The business test is leave-one-country-out cross-sectional validation, not a future-year temporal backtest. Snapshot governance analysis is not presented as forecast validation. User scenarios are deterministic assumptions, not empirical forecasts.</p></section><section><h2>Reproduce</h2><p><a href="../shared/analyze.py">Main calculation path</a> · <a href="../shared/audit_research.py">Independent audit path</a> · <a href="../shared/results.json">Machine-readable results</a> · <a href="../shared/extraction_manifest.json">Source hashes</a></p></section></main><footer>Independent research · 22 November 2026</footer></body></html>'''
for c in studies:
 p=ROOT/c['slug'];p.mkdir(exist_ok=True);(p/'index.html').write_text(dashboard(c));(p/'methodology.html').write_text(methodology(c));(p/'project.json').write_text(json.dumps({'title':c['title'],'domain':c['domain'],'summary':c['subtitle'],'published':'2026-11-22','status':'published','url':'https://mariianyaas.github.io/daily-intelligence/2026-11-22/'+c['slug']+'/','topic':c['title']},indent=2,ensure_ascii=False))
cards=''.join(f'<a class="card" href="{c["slug"]}/"><span>{esc(c["domain"])}</span><h2>{esc(c["title"])}</h2><p>{esc(c["subtitle"])}</p></a>' for c in studies)
(ROOT/'index.html').write_text(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>The Absorption Problem | Financial &amp; Risk Intelligence</title><link rel="stylesheet" href="shared/app.css"></head><body><header><nav><a href="/">← Main research portfolio</a> <a href="shared/audit.html">Audit &amp; sources</a></nav></header><main><div class="eyebrow">Weekly Intelligence / 22 November 2026</div><h1>The Absorption Problem</h1><p class="lead">Seven new tests of who absorbs higher rates, working-capital pressure, governance frictions, digital investment and cultural-funding risk.</p><div class="cards">{cards}</div><section><h2>Contemporary research triggers</h2><p>Norges Bank’s 5 November rate decision and 11 November Financial Stability Report frame the cost-of-capital question. NBIM’s current public agenda on capital management, technology, governance and resilient long-horizon ownership frames the investor questions. These triggers formulate questions; they do not substitute for the primary records used in the calculations.</p><p><a href="https://www.norges-bank.no/en/topics/monetary-policy/Monetary-policy-meetings/2026/november-2026/">Norges Bank rate decision, 5 November 2026</a> · <a href="https://www.norges-bank.no/en/news-events/news/Press-releases/2026/2026-11-11-fsr2/">Financial Stability Report, 11 November 2026</a> · <a href="https://www.nbim.no/en/news-and-insights/reports/2026/half-year-report-2026/web-report-half-year-report-2026/">NBIM half-year report 2026</a></p></section></main><footer>Independent research · Public-source evidence · 22 November 2026</footer></body></html>''')
