for c in studies:
 rec={'title':c['title'],'domain':c['domain'],'summary':c['subtitle'],'published':'2026-11-22','status':'published','url':'https://mariianyaas.github.io/daily-intelligence/2026-11-22/'+c['slug']+'/','topic':c['title']}
